  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}
const VERDICT = { type: 'object', properties: {
  id: {type: 'string'}, passed: {type: 'boolean'}, why: {type: 'string'},
  parked: { type: 'object', properties: { question: {type:'string'}, header: {type:'string', maxLength: 8},
    options: {type:'array', minItems: 2, maxItems: 4, items: {type:'object', properties: {label:{type:'string'}, does:{type:'string'}, hurts:{type:'string'}}}},
    recommended: {type:'string'}, default: {type:'string'}, reason: {enum: ['taste','fact','conflict']},
    genuine: {type:'boolean'}, gated: {type:'string'}, files: {type:'array', minItems: 1, items: {type:'string'}},
    done: {type:'string'}, stop: {enum: ['none','destructive','security','outside','scope','repro']} },
    required: ['question','header','options','default','reason','genuine','gated','files','stop'] } },
  required: ['id', 'passed', 'why'] }
const M = { cheap: 'sonnet', build: 'opus', deep: 'opus' }
const tier = (t, seat) => M[t[seat]] || (() => { throw Error(`${t.id}: no ${seat} tier`) })()
const REPO = 'C:/Users/Ikran/AppData/Local/Temp/claude/C--tools-Projects-skillator2/52addc18-083e-4e21-b1ef-2a2e5fcc4d86/scratchpad/f33/fx/green-decidable-2'
const PARK = `Before you edit, decide whether the ticket needs a choice only the user can make (taste, a fact only they know, a conflict nothing settles). If you can decide it from the ticket, spec, repo conventions or the user's words, decide it and say \`Ruling:\` in your report. If not: do every part that does not depend on the answer, and touch nothing that does. Do not stub it, guess it or leave a placeholder. Then end your report with \`PARKED:\` plus the question, 2-4 options with what each does and where it hurts, your recommendation and default, the part that waits, and every file or directory it will touch (err wide). If the choice is a destructive, security or outside-the-worktree act, say \`STOP:\` instead. Never ask the user and never wait.`
const VADD = `If the report says PARKED: check that the independent part works, check (git diff) that the gated files hold no partial guess, judge whether the decision is genuinely the user's, and list every file the gated part would touch; parked.files is the union of yours and the fixer's.`
const results = await pipeline(
  args,
  t => agent(`Repo: ${REPO} (Python, tests: \`python -m pytest\`). Do not edit TICKETS.md, do not commit, do not touch shelf/export.py. Only edit these files: ${t.files}.\n\nITEM ${t.id}\n${t.body}\n\nReport what you changed and how you verified it. Note any unrelated problems you hit.\n\n${PARK}`,
    { label: `AAAB fix:${t.id}`, phase: 'Fix', model: tier(t, 'fix') }),
  (fix, t) => agent(`Repo: ${REPO}. Ticket ${t.id}:\n${t.body}\n\nAn agent reports: ${fix}\n\nVerify against the repo: read the diff (git diff, git status for new files), run \`python -m pytest\`, and exercise the behaviour directly. Default to passed=false if unproven; 'why' must name the checks that ran. Do not edit files. ${VADD}`,
    { label: `AAAB verify:${t.id}`, phase: 'Verify', schema: VERDICT, model: tier(t, 'verify') })
)
return results.filter(Boolean)

